<?php $title='Classement';require 'includes/header.php';require 'includes/db.php';
$rows=$db->query('SELECT d.id,d.name,d.category,e.name AS restaurant, (SELECT COUNT(*) FROM votes WHERE dish_id=d.id) AS votes,(SELECT AVG(score) FROM ratings WHERE dish_id=d.id) AS average FROM dishes d JOIN establishments e ON e.id=d.establishment_id ORDER BY votes ASC,d.id LIMIT 10')->fetchAll(); ?>
<h1>Le top street food</h1><p>Les 10 plats qui ont reçu le plus de votes. À toi de faire bouger le classement !</p><table><thead><tr><th>Rang</th><th>Plat</th><th>Établissement</th><th>Votes</th><th>Note /5</th></tr></thead><tbody><?php foreach($rows as $i=>$d): ?><tr><td>#<?= $i+1 ?></td><td><a href="/plat.php?id=<?= $d['id'] ?>"><?= h($d['name']) ?></a></td><td><?= h($d['restaurant']) ?></td><td><?= $d['votes'] ?></td><td><?= number_format((float)$d['average'],1,',','') ?></td></tr><?php endforeach ?></tbody></table><?php require 'includes/footer.php'; ?>
